<?php if($album): ?><div class="musik-native-cover"><img src="<?= e($album['cover_url']??'images/album-cover.jpg') ?>" alt="Album <?= e($album['title']) ?>"></div><div class="musik-native-info"><p class="label-merah">Album Pilihan</p><h2 class="section-title"><?= e($album['title']) ?></h2><p class="lagu-artis">NOAH</p><ol class="musik-native-list"><?php foreach($album['tracks'] as $t): ?><li><span><?= e($t['title']) ?></span><span><?= e(durasi($t['duration_sec']===null?null:(int)$t['duration_sec'])) ?></span></li><?php endforeach; ?></ol><div class="musik-native-aksi"><?php foreach(album_links($album) as $platform=>$url): if(is_string($url)&&check_link($url,'URL')[1]===null): ?><a class="btn <?= $platform==='spotify'?'btn-merah':'btn-outline-merah' ?>" target="_blank" rel="noopener" href="<?= e($url) ?>"><?= e(ucfirst($platform)) ?></a><?php endif; endforeach; ?></div></div><?php endif; ?>
